import{_ as s,l as n,o as e,c as d,v as t,p as l,x as r,d as i,i as h,S as B}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"StarCoder / StarCoder2","description":"","frontmatter":{"title":"StarCoder / StarCoder2","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/starcoder.md","filePath":"llm/starcoder.md","lastUpdated":1789023840000}'),S={name:"llm/starcoder.md"};function p(c,a,g,C,m,u){const o=n("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="starcoder-starcoder2" tabindex="-1">StarCoder / StarCoder2 <a class="header-anchor" href="#starcoder-starcoder2" aria-label="Permalink to &quot;StarCoder / StarCoder2&quot;">​</a></h1><div class="epigraph"><p>BigCode 把可许可的源代码档案做成可检查、可退出的预训练集：15.5B 在 The Stack 上吃 1T token，下一代改用 Software Heritage 上的 The Stack v2，把 3B 训到超过上一代 15.5B Base。</p><footer>—— Li 等，StarCoder，arXiv:2305.06161；Lozhkov 等，StarCoder2，arXiv:2402.19173</footer></div><p>BigCode（Hugging Face、ServiceNow 等）的 <strong>StarCoder</strong> 线是开源代码模型里数据治理与架构配方写得最完整的一组。第一代：<strong>StarCoderBase 15.5B</strong> 在 The Stack（允许性许可证、opt-out）上训 <strong>1T</strong> token，再在 <strong>35B</strong> Python token 上得到 <strong>StarCoder</strong>；8K 上下文，<strong>MQA</strong>，<strong>FIM</strong>，TMLR 2023，arXiv:2305.06161。第二代 <strong>StarCoder2</strong>：<strong>3B / 7B / 15B</strong>，The Stack v2（Software Heritage，600+ 语言，体积约 4×），上下文 <strong>16384</strong>、滑动窗 <strong>4096</strong>，<strong>GQA</strong>，3B/7B 约 <strong>3.3T</strong>、15B 约 <strong>4.3T</strong> token，arXiv:2402.19173。本篇写两代差分；不把 SantaCoder 1.1B 或后来的指令版当成 Base 主表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>闭源 Codex 把 HumanEval 抬起来，开源缺的是：可合法再分发的大规模代码；训练时就见过 IDE 式中间填空；推理时大 batch 补全要省 KV。The Stack 用许可证过滤与退出流程，而不是「能爬就训」。文件级随机取样仍看不到跨文件依赖——后代 <a href="/llm/deepseek-coder">DeepSeek-Coder</a> 才把仓库组包写进预训练；StarCoder 要先把<strong>多语言 Base + Python 特化 + FIM + 8K</strong>做成可复现基线。</p><p>StarCoder2 面对的是：v1 语言覆盖与体积不够；15.5B 对端侧仍大；绝对位置 8K 外推弱。问题变成：用 SWH 档案扩语言，把小模型训过上一代大 Base，并把窗口做到 16K 而不把注意力做成满 16K 二次。</p><h3 id="base-与-python-特化不要混名" tabindex="-1">Base 与 Python 特化不要混名 <a class="header-anchor" href="#base-与-python-特化不要混名" aria-label="Permalink to &quot;Base 与 Python 特化不要混名&quot;">​</a></h3><p>StarCoderBase：80+ 语言、GitHub issues、commit、Jupyter，1T token。StarCoder：同一 15.5B 再吃 35B Python。评测上 Python 特化仍保其它语言，是论文主张；引用必须写是 Base 还是 Python 版。架构：GPT-2 式解码器，<strong>MQA</strong>，学得的绝对位置，FlashAttention，FIM 训练（Bavarian 等，见 <a href="/llm/fim-decode">FIM 解码</a>）。词表约 49K。PII 红线与归属追踪工具是发布的一部分，不是博客装饰。</p><p><span class="marginnote">StarCoder2-15B 没有再做一代那种单独 35B Python 续训；多语言 v2 与更长训练替代了「先通吃再特化 Python」的两段式。不要把 StarCoder 的 35B Python 故事抄到 2 的模型卡上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>The Stack v1.2：允许性许可证仓库，opt-out 排除。过滤规则（平均行长、最大行长、字母比例等）被后来许多代码模型沿用。FIM 把文件切成前缀 / 中段 / 后缀，训练时按哨兵拼接，使补全条件于两侧。MQA：多查询共享 KV，补全服务里大 batch 省缓存。</p><p>The Stack v2：与 Software Heritage 合作，619 种语言的档案标识（SWHID）公开，另加 PR、Kaggle、文档等。3B/7B/15B 用 NeMo 在 Eos Supercomputer（DGX H100）上训。注意力改为 <strong>GQA</strong>，位置改为 RoPE 一类相对编码（相对一代绝对位置），16K 上下文配 <strong>4K 滑动窗</strong>——长程是局部窗的堆叠，不是每层满 16K 稠密。FIM 保留。许可 OpenRAIL，数据可追溯到 SWHID。</p><h3 id="小模型打过上一代大-base" tabindex="-1">小模型打过上一代大 Base <a class="header-anchor" href="#小模型打过上一代大-base" aria-label="Permalink to &quot;小模型打过上一代大 Base&quot;">​</a></h3><p>2 的主张：StarCoder2-3B 在多数代码基准上超过同尺寸对照，并且超过 <strong>StarCoderBase-15B</strong>；15B 可打到或超过更大的 CodeLlama-34B 一档，在高资源补全上仍可能落后当时的 DeepSeekCoder-33B，但在数学、代码推理与部分低资源语言上更好。这是数据与训练长度的故事：3B×3T+ 对 15.5B×1T 的陈旧混合。指令版与评测提示不在 Base 主文展开。</p>',14)),(e(),l(B,null,{default:r(()=>[h(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22The%20Stack%20%E5%85%81%E8%AE%B8%E6%80%A7%E8%AE%B8%E5%8F%AF%20%2B%20opt-out%22%5D%20--%3E%20B%5B%22StarCoderBase%2015.5B%201T%208K%20MQA%22%5D%0A%20%20B%20--%3E%20PY%5B%22%2B35B%20Python%20%E2%86%92%20StarCoder%22%5D%0A%20%20S2%5B%22The%20Stack%20v2%20SWH%20600%2B%20%E8%AF%AD%E8%A8%80%22%5D%20--%3E%20F%5B%223B%2F7B%2F15B%203.3%E2%80%934.3T%22%5D%0A%20%20F%20--%3E%20GQA%5B%22GQA%20%2B%2016K%20%2F%20%E6%BB%91%E7%AA%97%204K%20%2B%20FIM%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>FIM 改的是排列：中段出现在后缀之后，梯度让模型在看见调用方时填实现，见 Bavarian；StarCoder 把它做成预训练默认比例，而不是只在微调补。MQA/GQA 改的是 KV 头数：补全时 batch 里许多请求共享同一套深网络，KV 带宽往往先爆。8K 让「文件上方的类」与「下方的测试」同时进窗口，仍远小于仓库；2 的 16K 加滑窗把更长文件放进训练，但滑窗意味着超过 4K 的依赖要靠层间传递，不是单层全局。</p><p>v2 的治理机制是可引用的 SWHID：权重与数据清单分开，opt-out 与许可证可审计。这与「爬到什么训什么」的闭源叙述相反，也解释了为何许多后续配方（含 DeepSeek-Coder 的过滤规则）要引用 The Stack。</p><h3 id="和-codestral、和仓库级组包" tabindex="-1">和 Codestral、和仓库级组包 <a class="header-anchor" href="#和-codestral、和仓库级组包" aria-label="Permalink to &quot;和 Codestral、和仓库级组包&quot;">​</a></h3><p><a href="/llm/codestral">Codestral</a> 是 22B 产品级代码模型，FIM 与 80+ 语言是同一产品意图，数据与许可（MNPL）不同。<a href="/llm/deepseek-coder">DeepSeek-Coder</a> 把依赖解析组包写进预训练，明确对照「StarCoder 式文件过滤仍可能留 fork」。StarCoder2 仍以文件 / 档案语料为主，16K 不是仓库图。评测上不要用 HumanEval Python 一列宣布低资源语言胜利。</p><p><span class="marginnote">2 的 16K 是训练窗口；滑窗 4096 是注意力模式。实现若关掉滑窗做满 16K，算力与论文配方不一致，外推数字不能当论文结果。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>OpenRAIL 不是 Apache：使用与再分发有行为约束，商用读许可证。opt-out 之后的快照与你下载的权重可能有时间差。PII 红线降低但不消灭密钥泄漏，输出仍要扫描。FIM 推理必须用训练哨兵，聊天模板冒充中间填空会和后缀打架。15.5B 一代用绝对位置，强行超 8K 要另做外推，不要假设与 2 的 RoPE 相同。</p><p>不要把 StarCoderPlus / StarChat 的指令数字写进 Base。不要把 15B-2 写成 15.5B 的继续训——数据与结构都换了。HumanEval 污染随时间变差，应用自有仓库回归。低资源语言「600+」是档案覆盖，不是每种语言都有 15B 级 token。</p><p>IDE 集成要把前缀缓存键包含 FIM 后缀。滑窗实现与 FlashAttention 版本绑在一起，升级内核要回归补全一致性。归属工具可查疑似抄训练集，不能当许可证合规的充分条件。过滤规则把平均行长与字母比例当质量代理，会误伤压缩过的生成代码，也会放过「看起来像源码的数据文件」；上线前应用自己的语言与仓库再滤一层，不要假设 The Stack 的阈值等于你们的生产阈值。Issues 与 Jupyter 进预训练，是为了自然语言里的报错和笔记本工作流，不等于聊天指令模型；要把 StarChat 一类对话数字从 Base 表里拿掉。2 代 15B 在高资源补全上输给更大的稠密代码模型时，应看语言与基准分列，不要用一张平均分宣布「开源已经结束」。FIM 比例与 PSM/SPM 排列若与论文不同，中间补全回归会先坏，HumanEval 从左到右分数却仍能看——这是最容易漏测的差分。</p><p><span class="marginnote">出处：Li 等，<em>StarCoder: may the source be with you!</em>，arXiv:2305.06161；Lozhkov 等，<em>StarCoder 2 and The Stack v2: The Next Generation</em>，arXiv:2402.19173。SantaCoder 是 1.1B 前身。The Stack 数据集论文见 Kocetkov 等 2022。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>StarCoderBase 15.5B：The Stack、1T token、8K、MQA、FIM；StarCoder 再加 35B Python。</li><li>StarCoder2：3/7/15B，The Stack v2，3.3–4.3T，GQA，16K 配 4K 滑窗，FIM 保留。</li><li>数据可退出、可追溯是 BigCode 的一等贡献；3B-2 可超过 15.5B Base 是训练配方主张。</li><li>与仓库组包派、与 MNPL 的 Codestral 不是同一张卡。</li><li>出处：arXiv:2305.06161 与 arXiv:2402.19173。</li></ul>',13))])}const P=s(S,[["render",p]]);export{T as __pageData,P as default};
